import React from "react"
import {
    useSeededParticles,
} from "../useSeededParticles"

/** A twinkling starfield scattered across the viewport, tinted by the accent color. Motion-free (opacity pulse only). */
/** Props for {@link StarsEffect}. */
interface StarsEffectProps {
    /** Particle count. */
    count?: number
}

export const StarsEffect = ({ count = 70 }: StarsEffectProps) => {
    const particles = useSeededParticles(count, 71)
    return (
        <>
            {particles.map((p) => (
                <span
                    key={p.index}
                    className="ambient-star absolute rounded-full"
                    style={{
                        left: `${p.left}%`,
                        top: `${p.top}%`,
                        width: `${Math.max(1, p.size - 2)}px`,
                        height: `${Math.max(1, p.size - 2)}px`,
                        background: "var(--accent)",
                        animation: `starTwinkle ${p.duration / 2 + 1.5}s ease-in-out infinite ${p.delay}s`,
                    }}
                />
            ))}
        </>
    )
}

"use client"

import React from "react"
import type { ReactNode } from "react"
import { Button, ButtonGroup, cn } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** One selectable button in a {@link FlexWrapButtonRadio}. */
export interface FlexWrapButtonRadioItem<T extends string> {
    /** Value selected when this button is chosen. */
    value: T
    /** Button content (icon + label + meta ΓÇö caller-defined inline row). */
    content: ReactNode
    /** When true the button is dimmed and not selectable. */
    isDisabled?: boolean
}

/** Props shared by both the single- and multi-select modes of {@link FlexWrapButtonRadio}. */
interface FlexWrapButtonRadioBaseProps<T extends string> extends WithClassNames<undefined> {
    /** The selectable buttons. */
    items: Array<FlexWrapButtonRadioItem<T>>
    /** Accessible label for the group. */
    ariaLabel: string
    /**
     * Optional trailing node placed after the buttons in the SAME row (e.g. a
     * "+N" overflow button). Not part of the group's value ΓÇö it's an action.
     */
    trailing?: ReactNode
    /**
     * Optional per-item trailing action(s) ΓÇö e.g. a delete button and/or a "..."
     * (kebab) menu trigger. When provided, the item's select button and these
     * action buttons render as ONE connected {@link ButtonGroup} per item
     * (`[select | delete | ...]`) ΓÇö touching, a full-height separator at every seam,
     * rounded only at the two outer ends ΓÇö instead of a detached button floating
     * beside the pill. Return the action `<Button>`s as an ARRAY (with `key`s) so
     * each is an individual segment the group can rounded/separate ΓÇö NOT wrapped in
     * a fragment (a fragment counts as one child and the per-button separator
     * injection would misfire). Omit for a plain single-select row (default ΓÇö
     * matches every existing caller's output). The actions are SIBLINGS of the
     * select button (a `<Button>` can't nest another interactive element), so a
     * click on one never changes the selection.
     */
    itemAction?: (item: FlexWrapButtonRadioItem<T>) => ReactNode
}

/** Single-select mode (default) ΓÇö exactly one value selected at a time. */
interface FlexWrapButtonRadioSingleProps<T extends string> extends FlexWrapButtonRadioBaseProps<T> {
    /** Single-select ΓÇö omit or pass `false`. */
    multiple?: false
    /** Currently selected value. */
    value: T
    /** Fired with the chosen value when a button is selected. */
    onChange: (value: T) => void
}

/**
 * Multi-select mode ΓÇö a SET of values, each button an independent toggle. The
 * caller owns the set + the toggle logic (e.g. enforcing "at least one selected");
 * this component only reports which button was pressed via {@link onToggle}.
 */
interface FlexWrapButtonRadioMultiProps<T extends string> extends FlexWrapButtonRadioBaseProps<T> {
    /** Multi-select ΓÇö pass `true`. */
    multiple: true
    /** Currently selected values. */
    values: Array<T>
    /** Fired with the pressed value (the caller adds/removes it from its own set). */
    onToggle: (value: T) => void
}

/** Props for the {@link FlexWrapButtonRadio} block ΓÇö a discriminated union on `multiple`. */
export type FlexWrapButtonRadioProps<T extends string> =
    | FlexWrapButtonRadioSingleProps<T>
    | FlexWrapButtonRadioMultiProps<T>

/**
 * A single-select toggle-button group laid out as a flex-wrap row (buttons wrap
 * to the next line, never scroll). Every option is a real HeroUI `<Button>`:
 * standalone, selected = filled `tertiary` (NEUTRAL, not accent ΓÇö a facet/config
 * toggle isn't a CTA), unselected = hollow `ghost` ΓÇö clean, no own surface (the
 * parent card, or the bare page, is the surface). NEVER `primary` here ΓÇö a config row commonly
 * sits on the SAME surface as the page's one accent CTA, and a solid-primary
 * selected pill would compete with it (1 accent-solid / surface, Von Restorff ΓÇö
 * `accent-system`).
 *
 * When `itemAction` is supplied, each item instead renders as one connected
 * {@link ButtonGroup} ΓÇö the select button + its action button(s) touching, only
 * the two outer ends rounded (`[select | delete | ...]`). No bordered frame: the button
 * VARIANTS carry the look ΓÇö EVERY segment is filled `--default` so the cluster
 * reads as one solid control (the select pill is `secondary` = default fill +
 * accent text when chosen, else `tertiary` = default fill + neutral text ΓÇö NOT a
 * hollow `ghost`, which would leave the unselected label floating on the page; the
 * action buttons are `tertiary` too). The seam is HeroUI's own
 * `ButtonGroup.Separator`, recoloured to the `--border` token (`!bg-border
 * !opacity-100`, overriding its default muddy `bg-current opacity-15`) so it
 * matches every other divider in the app. Because `.button` is
 * `position: relative`, the separator MUST live INSIDE the button that follows the
 * seam (its `left: -1px` then bites that button's left edge); so the component
 * injects one at the head of each action button's children ΓÇö callers just return
 * plain `<Button>`s. Overridden to FULL height (`!top-0 !h-full`) from HeroUI's
 * default 50%.
 *
 * `role="group"` + `aria-pressed` per button ΓÇö works for BOTH the default
 * single-select toggle group and the multi-select mode (`multiple`, a SET of
 * pressed toggles; the caller owns add/remove + any "keep ΓëÑ1 selected" rule). For
 * a grid with description/badge use `SelectableCardGroup`.
 *
 * @param props - {@link FlexWrapButtonRadioProps}
 * @see Story: .storybook/stories/blocks/navigation/FlexWrapButtonRadio/FlexWrapButtonRadio.stories
 */
export const FlexWrapButtonRadio = <T extends string>(props: FlexWrapButtonRadioProps<T>) => {
    const { items, ariaLabel, trailing, itemAction, className } = props
    // narrow the discriminated union once ΓÇö selection state + the press handler are
    // the only things that differ between single- and multi-select.
    const isSelected = (candidate: T): boolean =>
        (props.multiple ? props.values.includes(candidate) : props.value === candidate)
    const onItemPress = (candidate: T): void => {
        if (props.multiple) {
            props.onToggle(candidate)
        } else {
            props.onChange(candidate)
        }
    }
    return (
        <div role="group" aria-label={ariaLabel} className={cn("flex flex-wrap items-center gap-2", className)}>
            {items.map((item) => {
                const selected = isSelected(item.value)
                if (!itemAction) {
                    // standalone: selected = filled `tertiary` (neutral, NOT accent ΓÇö
                    // a facet toggle isn't a CTA), unselected = hollow `ghost` (no
                    // surface of its own ΓÇö the page/card is the surface).
                    return (
                        <Button
                            key={item.value}
                            size="sm"
                            variant={selected ? "tertiary" : "ghost"}
                            isDisabled={item.isDisabled}
                            aria-pressed={selected}
                            onPress={() => onItemPress(item.value)}
                        >
                            {item.content}
                        </Button>
                    )
                }
                // select button + its action(s) = ONE connected ButtonGroup per
                // item. No border frame ΓÇö the button variants carry the look; here
                // the unselected select is `tertiary` (filled `--default`), NOT
                // `ghost`, so it matches the filled action buttons instead of
                // floating hollow. Each action button gets a `ButtonGroup.Separator`
                // injected at the head of its children (HeroUI's separator must sit
                // INSIDE the following button ΓÇö see the class doc), full-height.
                return (
                    <ButtonGroup key={item.value} size="sm" className="w-fit">
                        <Button
                            size="sm"
                            variant={selected ? "secondary" : "tertiary"}
                            isDisabled={item.isDisabled}
                            aria-pressed={selected}
                            onPress={() => onItemPress(item.value)}
                        >
                            {item.content}
                        </Button>
                        {React.Children.map(itemAction(item), (action) =>
                            React.isValidElement<{ children?: ReactNode }>(action)
                                ? React.cloneElement(
                                    action,
                                    undefined,
                                    <ButtonGroup.Separator className="!top-0 !h-full !bg-border !opacity-100" />,
                                    action.props.children,
                                )
                                : action,
                        )}
                    </ButtonGroup>
                )
            })}
            {trailing}
        </div>
    )
}

"use client"

import React from "react"
import { CodePreviewTabs } from "../CodePreviewTabs"

/**
 * One pane inside a `:::tab` block: the source code (`:::code` ΓåÆ ` ```tsx ` Shiki) or the live
 * demo (`:::preview` ΓåÆ ` ```mdx ` render). It only renders its children (the fence rendered by the
 * normal `pre` handler); {@link TabsBlock} identifies which pane is which by the original directive
 * tag name (`tabcode`/`tabpreview`), not by this prop.
 */
interface TabPaneProps {
    kind: "code" | "preview"
    children?: React.ReactNode
}

export const TabPane = (
    { children }: TabPaneProps,
) => <>{children}</>

/** The hast node react-markdown threads onto every element renderer via the `node` prop. */
interface NodeProp {
    node?: { tagName?: string }
}

/** Props for {@link TabsBlock}. */
interface TabsBlockProps {
    children?: React.ReactNode
}

/**
 * Renders a `:::tab` block as **[ Preview | Code ]** tabs via the shared {@link CodePreviewTabs}.
 *
 * Use this (not a single ` ```mdx `) when the real code has logic/imports that can't be evaluated:
 * the `:::code` pane shows the FULL code (Shiki, not rendered) and the `:::preview` pane shows a
 * separate renderable demo.
 *
 * Panes are matched by the original directive tag name carried on each child's `node` prop
 * (`tabcode` / `tabpreview`) ΓÇö order-independent. NOTE: the children TabsBlock receives are the
 * `tabcode`/`tabpreview` element renderers themselves, whose own props are only `{ node, children }`;
 * the `kind` lives on the `TabPane` they *return*, so it is NOT visible here ΓÇö match on `node.tagName`.
 * @param props.children - The `:::code` / `:::preview` pane elements.
 */
export const TabsBlock = ({ children }: TabsBlockProps) => {
    let previewNode: React.ReactNode = null
    let codeNode: React.ReactNode = null
    React.Children.forEach(children, (child) => {
        if (!React.isValidElement(child)) {
            return
        }
        const tagName = (child.props as NodeProp).node?.tagName
        if (tagName === "tabpreview") {
            previewNode = child
        } else if (tagName === "tabcode") {
            codeNode = child
        }
    })

    if (previewNode == null && codeNode == null) {
        return <>{children}</>
    }
    return <CodePreviewTabs preview={previewNode} code={codeNode} />
}

"use client"
import React, { PropsWithChildren } from "react"
import { useTranslations } from "next-intl"
import { useSelectedLayoutSegments, useSearchParams } from "next/navigation"
import { Spinner } from "@/components/atoms/display/Spinner"
import { _LearnShellLayout } from "./component"
import { ContentMap } from "@/components/blocks/learn/ContentMap"
import { MilestoneOutline } from "@/components/blocks/learn/MilestoneOutline"
import { LeaderboardCategoryRail } from "@/components/blocks/learn/LeaderboardCategoryRail"
import { OnThisPage } from "@/components/blocks/learn/OnThisPage"
import { ContentAiSelectionAsk } from "@/components/blocks/learn/ContentAiSelectionAsk"
import { EnrollGate } from "@/components/blocks/learn/EnrollGate"
import { PersonalProjectGatePreview } from "@/components/blocks/learn/personal-project/PersonalProjectGatePreview"
import { GithubLinkGate } from "@/components/blocks/auth/GithubLinkGate"
import { ResizableRail } from "@/components/blocks/layout/ResizableRail"
import { useQueryCourseSwr } from "@/hooks/swr/api/graphql/queries/useQueryCourseSwr"
import { useQueryCourseEnrollmentStatusSwr } from "@/hooks/swr/api/graphql/queries/useQueryCourseEnrollmentStatusSwr"
import { useAppSelector } from "@/redux/hooks"

/**
 * Learn surfaces that require enrollment. Only the capstone (personal-project) is gated:
 * it's the enrolled-only hands-on outcome. Trial viewers ("Try for free") may freely browse the
 * rest ΓÇö flashcards (non-premium), leaderboard, foundations, content + mind-map ΓÇö so those
 * are NOT gated. Keyed by `segments[0]`.
 */
const ENROLL_REQUIRED_SURFACES: ReadonlySet<string> = new Set([
    "personal-project",
])

/** i18n key for each gated surface's display name (folded into the gate title). */
const SURFACE_LABEL_KEY: Record<string, string> = {
    "personal-project": "finalProject.title",
}

/** Per-surface MOCK teaser rendered behind the enroll card (Medium-style gate). */
const SURFACE_PREVIEW: Record<string, React.ReactNode> = {
    "personal-project": <PersonalProjectGatePreview />,
}

/** Learn course shell: left/right rails, enroll gate, and full-bleed work surfaces. */
export const LearnShellLayout = ({ children }: PropsWithChildren) => {
    const t = useTranslations()
    // load the active course here so EVERY learn tab has `course.entity` on a cold refresh
    // (the displayId is synced from the URL by a global effect). Tabs like personal-project
    // have no other loader, and downstream queries (milestones, etc.) gate on `course.id`.
    useQueryCourseSwr()
    // enrollment status drives the enroll-gate on hands-on surfaces (populates state.user.enrolled).
    const enrollmentSwr = useQueryCourseEnrollmentStatusSwr()
    const enrolled = useAppSelector((state) => state.user.enrolled)
    // `enrolled` defaults to false, so only trust it once the status query has settled ΓÇö
    // otherwise an enrolled viewer would flash the gate on cold load.
    const enrollKnown = Boolean(enrollmentSwr.data) || Boolean(enrollmentSwr.error)
    // which learn sub-route is active. Docs-style layout:
    //  - "modules" (module list / detail / content) ΓåÆ content-map on the LEFT (persistent)
    //    + an on-this-page outline on the RIGHT (self-hides when the body has no headings).
    //  - "personal-project" ΓåÆ its milestone rail on the LEFT too (same place as the content-map),
    //    so the capstone reads like every other learn tab; no right rail.
    // every other tab (mind-map, foundations, headhuntings, practice, leaderboard, starci-ai)
    // has no side rails, so its content spans the full width.
    // lessons now live UNDER the content home (`/learn/content/modules/...`), so the
    // immediate child segment is "content" for BOTH the dashboard home and the reader.
    // Use the full segment list: `includes("modules")` flags the reader/module routes,
    // while `segments[0]` flags the top-level tabs (content / personal-project / mind-map).
    const segments = useSelectedLayoutSegments()
    const searchParams = useSearchParams()
    const isModules = segments.includes("modules")
    // the course-content home (`/learn/content`) + the lesson reader (`/content/modules/...`)
    // both share the content-map rail on the LEFT: the full module ΓåÆ lesson tree lives in
    // the rail (its one home), and the dashboard body shows continue + progress + the
    // current-module path instead of re-drawing the whole tree.
    const isContent = segments[0] === "content"
    const isPersonalProject = segments[0] === "personal-project"
    // the flashcards surface goes RAIL-LESS entirely (per concepts/when-rail: drop the 2nd rail
    // for the whole Flashcards/Review surface). The deck list lives IN the pane (study overview) and the
    // mode switch is in-pane on desktop too. `isFlashcards` only drives the mobile-bar choice.
    const isFlashcards = segments[0] === "flashcards"
    // the "Quick quiz" surface goes full-bleed ONLY during a live run (a focused work
    // surface: its own `WorkSessionHeader` band IS the header) ΓÇö detected off the
    // dedicated resumable route (`flashcards/quiz/sessions/[sessionId]`), same
    // pattern as the mock-interview's `isMockInterviewInterviewRoute` below.
    const isFlashcardQuizLive = isFlashcards && segments[1] === "quiz" && segments[2] === "sessions"
    // "Study cards"/"Due review" live session goes full-bleed ONLY during a live session
    // ΓÇö same idiom, detected off the dedicated resumable route
    // (`flashcards/review/sessions/[sessionId]`, 2026-07-11 correction: "card review UI matches study"). This ONE route now serves BOTH FlashcardReviewer
    // (single-deck) and DueReview (cross-deck) ΓÇö the old deck-scoped route
    // (`review/decks/[deckId]/sessions/[sessionId]`) was consolidated away; the
    // bare `.../review` overview route (no `sessions` segment) is just the
    // resolve-only shim ΓÇö stays centered, never full-bleed. Correction
    // 2026-07-12: the gate still checked the DELETED deck-scoped shape and
    // never matched the real route, so the shell kept applying its `p-6`
    // reading-column padding ON TOP of the surface's own full-bleed padding
    // (teacher: "drop padding-6 here", pointed at DevTools showing the shell's
    // `p-6 @max-app-lg:pb-16` wrapper still active on a live review session).
    const isFlashcardReviewLive = isFlashcards && segments[1] === "review" && segments[2] === "sessions"
    // the mind-map is a full-bleed interactive canvas (fills the viewport edge-to-edge),
    // so it opts out of the shell's canonical p-6 reading-column padding.
    const isMindMap = segments[0] === "mind-map"
    // the mock interview goes full-bleed ONLY during the live `interview` phase (a focused
    // work surface: conversation + tool workspace). setup/grading/scorecard stay centered.
    // The active phase is mirrored into the URL (`?phase=interview`) by MockInterviewSession
    // so the shell can drop the course rails + reading padding for that phase only.
    const isMockInterview = segments[0] === "mock-interview"
    // the dedicated resumable route (`mock-interview/interview/[sessionId]`) is
    // ALWAYS the live work surface ΓÇö detected straight off the path segment so
    // there is no `?phase=interview` round-trip to wait on before the shell
    // drops its rails. Additive: the legacy `?phase=interview` query-param
    // mirror (still written by MockInterviewSession once mounted) keeps working
    // for the same route too.
    const isMockInterviewInterviewRoute = isMockInterview && segments[1] === "interview"
    const isMockInterviewLive = isMockInterviewInterviewRoute || (isMockInterview && searchParams.get("phase") === "interview")
    // a live quiz / interview grades a recruiter-facing signal ΓåÆ the AI chat is a
    // cheat channel there and gets suppressed (mirrors the same gate in InnerLayout,
    // which also kills a rail the learner left open before navigating in).
    const isAssessmentLive = isFlashcardQuizLive || isMockInterviewLive
    // ONLY the session (`ΓÇª/playground/<slug>/session`) is a full-bleed work
    // surface (step guide + terminal/resources tabs), same reasoning as the live
    // mock-interview route. The exercise's SETUP page (`ΓÇª/playground/<slug>`) and
    // the hub list (`ΓÇª/playground`) are reading surfaces ΓÇö install + pair
    // guidance, progress, machine status ΓÇö so they keep the normal reading column.
    const isPlaygroundSession = segments[0] === "playground" && segments[2] === "session"
    // the leaderboard shows its XP-category selector as a sidebar (like the content
    // page) on the LEFT; the board reads the selection from the `?category=` URL param.
    const isLeaderboard = segments[0] === "leaderboard"
    // a single challenge (`ΓÇª/contents/<id>/challenges/<id>`) KEEPS the course-tree rail (the
    // learner still navigates the course while solving), but its body is a tabbed single column
    // (Brief / Submit), so it needs no on-this-page outline. Only the right rail is dropped.
    const isChallenge = segments.includes("challenges")

    // persistent left rail (always visible on desktop): the width is drag-resizable
    // (persisted) via ResizableRail; sticky under the navbar and a flex column bounded to
    // the viewport so the rail pins its header/search and scrolls ONLY the list. Hidden
    // below lg (mobile opens it in the LearnMobileBar drawer).
    const railClass = "hidden shrink-0 @app-lg:flex @app-lg:flex-col @app-lg:sticky @app-lg:top-16 @app-lg:self-start @app-lg:h-[calc(100dvh-4rem)]"

    // left rail: course content-map while reading lessons AND on the content home;
    // milestone outline for the capstone.
    const leftRail = (isModules || isContent) ? (
        <ResizableRail
            className={railClass}
            storageKey="starci.learn.contentMap.width"
            defaultWidth={320}
            minWidth={256}
            maxWidth={560}
            ariaLabel={t("courseContents.resizeRail")}
        >
            <ContentMap className="min-h-0 @app-lg:flex-1" />
        </ResizableRail>
    ) : isPersonalProject ? (
        <ResizableRail
            className={railClass}
            storageKey="starci.learn.milestoneMap.width"
            defaultWidth={320}
            minWidth={256}
            maxWidth={560}
            ariaLabel={t("courseContents.resizeRail")}
        >
            <MilestoneOutline className="min-h-0 @app-lg:flex-1" />
        </ResizableRail>
    ) : isLeaderboard ? (
        <ResizableRail
            className={railClass}
            storageKey="starci.learn.leaderboardRail.width"
            defaultWidth={300}
            minWidth={240}
            maxWidth={420}
            ariaLabel={t("leaderboard.categories.label")}
        >
            <LeaderboardCategoryRail variant="rail" className="min-h-0 @app-lg:flex-1" />
        </ResizableRail>
    ) : undefined
    // right rail: on-this-page for the LESSON READER only (a real "contents/<id>" route) ΓÇö
    // the module SHELL page (`/content/modules/<moduleId>`, no `contents` segment) is its own
    // dashboard (mirrors the course-content home, which also has no right rail) and would
    // otherwise inherit a stale TOC from whatever lesson was read last (OnThisPage self-hides
    // on `!contentId`, not on route ΓÇö the module shell has no active content of its own).
    const isLessonReader = isModules && segments.includes("contents")
    const rightRail = (isLessonReader && !isChallenge) ? (
        <OnThisPage />
    ) : undefined

    // The content-AI chat rail is NOT a learn concern any more: it docks beside the
    // whole app from `InnerLayout`, so the learn right-rail slot is free to keep
    // serving the surface's own outline again.

    // enroll-gate: a trial viewer hitting a hands-on surface sees the enroll CTA, not a broken
    // page. Only gate once enrollment is KNOWN (enrolled defaults false ΓåÆ would flash otherwise);
    // while it resolves, hold the surface (and its enrollment-bound hooks) back behind a spinner.
    const surface = segments[0]
    const isEnrollRequired = Boolean(surface) && ENROLL_REQUIRED_SURFACES.has(surface as string)
    const showSurface = !isEnrollRequired || (enrollKnown && enrolled)
    const isGated = isEnrollRequired && enrollKnown && !enrolled
    const gateLabelKey = surface ? SURFACE_LABEL_KEY[surface] : undefined

    const content = showSurface
        ? children
        : isGated
            ? (
                <EnrollGate
                    title={t("enrollGate.title", { surface: gateLabelKey ? t(gateLabelKey) : "" })}
                    description={t("enrollGate.description")}
                    preview={surface ? SURFACE_PREVIEW[surface] : undefined}
                />
            )
            : (
                <div className="flex justify-center py-12">
                    <Spinner />
                </div>
            )

    return (
        <>
            {/* soft prompt: nudge learners with no linked GitHub to connect once per session */}
            <GithubLinkGate />
            {/* The floating "ask StarCi AI" mascot button now mounts ONCE, globally,
                from `InnerLayout` (app-wide chat, reachable outside a course too) ΓÇö
                `InnerLayout` applies the same `isAssessmentLive` suppression during a
                live quiz / mock-interview (a course-grounded AI beside a
                recruiter-facing signal is a cheat channel). Chat returns after the
                session, on the scorecard, for "review weak tags". */}
            {/* "ask AI about this passage" button on lesson-article text selection */}
            {!isAssessmentLive ? <ContentAiSelectionAsk /> : null}
            <_LearnShellLayout
                leftRail={showSurface ? leftRail : undefined}
                rightRail={showSurface ? rightRail : undefined}
                fullBleed={isMindMap || isMockInterviewLive || isPlaygroundSession || isFlashcardQuizLive || isFlashcardReviewLive}
                simpleMobileBar={isLeaderboard || isFlashcards}
            >
                {content}
            </_LearnShellLayout>
        </>
    )
}

import React from "react"
import { ArrowRightIcon, ShoppingCartIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { DrawerShell } from "@/components/composites/layout/DrawerShell"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { Button } from "@/components/atoms/buttons/Button"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"
import { SurfaceListCard } from "@/components/blocks/cards/SurfaceListCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { PriceTagInline } from "@/components/blocks/commerce/PriceTag"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { CartLine } from "@/components/blocks/commerce/CartLine"
import type { CartItemEntity } from "@/modules/api/graphql/queries/types/my-cart"
import type { CoursesCheckoutPreviewLine } from "@/modules/api/graphql/queries/types/courses-checkout-preview"

/** All display text, already localized by the connected `MiniCartDrawer`; a story passes i18n keys. */
export interface MiniCartDrawerLabels {
    /** `"${cart.title} ┬╖ ${cart.itemsCount}"`, already interpolated with `count`. */
    header: string
    emptyTitle: string
    emptyDescription: string
    browseCourses: string
    errorTitle: string
    retry: string
    /** `cart.comboActive`/`cart.comboStart`, already picked+interpolated for the current `bundlePercent`. */
    comboLabel: string
    /** `cart.bundleBonus`, already interpolated ΓÇö only shown while `bundlePercent > 0`. */
    bundleBonusChip: string
    /** `cart.comboNextHint`/`cart.comboMaxHint`, already picked+interpolated for `nextTierPercent`. */
    comboHint: string
    total: string
    /** `cart.savings`, already interpolated ΓÇö only shown while `savingsVnd > 0`. */
    savings: string
    /** `cart.installmentHint`, already interpolated ΓÇö only shown while `cheapestMonthlyVnd` is set. */
    installmentHint: string
    checkout: string
    viewFullCart: string
}

/** Props for {@link _MiniCartDrawer} ΓÇö presentational; all data resolved, no fetch/store/i18n. */
export interface MiniCartDrawerProps {
    isOpen: boolean
    onOpenChange: (open: boolean) => void
    /** Slide-in edge. `true` on mobile ΓåÆ bottom sheet. */
    isMobile: boolean
    /** First load, nothing in hand ΓåÆ the cart-list zone shimmers in place (co-located). */
    isSkeleton?: boolean
    /** Settled with zero lines ΓåÆ the empty message replaces the list. */
    isEmpty?: boolean
    /** Truthy ΓåÆ the cart-list zone falls to the error message (beats loading + empty). */
    error?: unknown
    onRetry?: () => void
    onBrowseCourses?: () => void
    items?: Array<CartItemEntity>
    /** courseId ΓåÆ the real checkout-preview line, for per-line pricing. */
    previewByCourse?: Map<string, CoursesCheckoutPreviewLine>
    isMutating?: boolean
    onRemove: (courseId: string) => void
    /** Combo-meter fill (0..3). */
    itemCount?: number
    /** Whether the current bundle tier is above zero ΓÇö gates the bonus chip. */
    bundlePercent?: number
    /** First load of the checkout preview, cart already settled ΓåÆ the footer summary shimmers. */
    isPreviewSkeleton?: boolean
    /** The real checkout preview ΓÇö total/savings/installments. `undefined` while pending or on error. */
    preview?: { totalChargedVnd: number; totalListVnd: number; savingsVnd: number }
    /** `true` ΓåÆ the preview fetch settled with an error; falls back to `fallbackTotalVnd`. */
    previewError?: boolean
    /** Sum of entity display prices ΓÇö shown only when the preview failed to load. */
    fallbackTotalVnd?: number
    /** Cheapest installment monthly amount, already formatted. `null` ΓåÆ no installment plans exist. */
    cheapestMonthlyLabel?: string | null
    onCheckout?: () => void
    onViewFullCart?: () => void
    labels: MiniCartDrawerLabels
}

/**
 * Mini-cart drawer ΓÇö the presentational half of {@link _MiniCartDrawer}'s connected
 * `MiniCartDrawer` (`index.tsx`): the slide-out cart confirmation + combo meter,
 * right on desktop / bottom-sheet on mobile. Composed on `DrawerShell` (the shared
 * panel-scaffold composite): a bordered `SurfaceListCard` reusing {@link CartLine}
 * (the SAME row the `/cart` page uses), a bundle-discount `ProgressMeter`, and a
 * footer with the real charged total + saving, a primary "Checkout" and a text
 * link to the full cart page. `error`/`isEmpty` fall to the shared
 * `AsyncContentError` / `AsyncContentEmpty` composites; otherwise the tree renders
 * with `isSkeleton` threaded down so the shimmer mirrors the loaded shape
 * (loading-and-skeleton.md). See `tiers/split.md` ΓÇö the connected `index.tsx` owns
 * the fetch, the stores, and the i18n.
 *
 * @param props - {@link MiniCartDrawerProps}
 */
export const _MiniCartDrawer = ({
    isOpen,
    onOpenChange,
    isMobile,
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    onBrowseCourses,
    items = [],
    previewByCourse,
    isMutating = false,
    onRemove,
    itemCount = 0,
    bundlePercent = 0,
    isPreviewSkeleton = false,
    preview,
    previewError = false,
    fallbackTotalVnd = 0,
    cheapestMonthlyLabel = null,
    onCheckout,
    onViewFullCart,
    labels,
}: MiniCartDrawerProps) => {
    const comboLabelRow = [
        () => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text={labels.comboLabel} />,
        ...(isSkeleton
            ? [() => <Chip isSkeleton tone="accent" />]
            : bundlePercent > 0
                ? [() => <Chip tone="accent" text={labels.bundleBonusChip} />]
                : []),
    ]
    const comboMeterItems = [
        () => (
            <StackH
                gap={3}
                principle="flex-action"
                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                align="center"
                justify="between"
                items={comboLabelRow}
            />
        ),
        () => <ProgressMeter value={itemCount} max={3} isSkeleton={isSkeleton} />,
        () => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text={labels.comboHint} />,
    ]
    const comboMeterSection: ComponentTypeWithSkeleton = () => (
        <StackV gap={3} items={comboMeterItems} />
    )

    // Line list ΓÇö reuses the SAME `CartLine` as the `/cart` page. `bordered`: this
    // list is NESTED inside the drawer surface, where `shadow-surface` renders
    // invisible against the parent (dark mode) ΓÇö nested cards need a border to
    // delineate (`card.md` ┬ºsurface-in-surface). The `/cart` PAGE keeps it
    // un-bordered (top-level on `bg-background`, shadow shows). `CartLine` has no
    // co-located skeleton of its own, so the loading rows are mirrored by hand,
    // same shape (leading tile ┬╖ two text lines ┬╖ trailing action).
    const cartLineSkeletonItems = [
        () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
        () => (
            <StackV
                gap={3}
                classNames={["min-w-0", "flex-1"]}
                items={[
                    () => <Skeleton className="h-4 w-1/2 rounded-lg" />,
                    () => <Skeleton className="h-4 w-24 rounded-lg" />,
                ]}
            />
        ),
        () => <Skeleton className="size-9 shrink-0 rounded-lg" />,
    ]
    const cartListSection: ComponentTypeWithSkeleton = () => (
        <SurfaceListCard bordered>
            {isSkeleton
                ? Array.from({ length: 2 }).map((_row, index) => (
                    <StackH
                        key={index}
                        gap={1}
                        principle="card-padding"
                        explain="Card body inset ΓÇö not page-pad, because this is the surface padding of a card rather than the page chrome."
                        padding={5}
                        body={() => (
                            <StackH
                                gap={4}
                                principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                align="center"
                                items={cartLineSkeletonItems}
                            />
                        )}
                    />
                ))
                : items.map((item) => (
                    <CartLine
                        key={item.id}
                        item={item}
                        previewLine={previewByCourse?.get(item.courseId)}
                        onRemove={onRemove}
                        isMutating={isMutating}
                    />
                ))}
        </SurfaceListCard>
    )

    // Body ΓÇö error ΓåÆ skeleton ΓåÆ empty ΓåÆ content (BLOCK-8): the empty and error
    // surfaces are the shared `AsyncContent*` composites dropped in as their own
    // states; otherwise the ONE tree renders, with `isSkeleton` threaded down so
    // the shimmer mirrors the loaded shape.
    const cartBody: ComponentTypeWithSkeleton = () => {
        if (error) {
            return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
        }
        if (!isSkeleton && isEmpty) {
            return (
                <AsyncContentEmpty
                    icon={ShoppingCartIcon}
                    title={labels.emptyTitle}
                    description={labels.emptyDescription}
                    onRetry={onBrowseCourses}
                    retryLabel={labels.browseCourses}
                />
            )
        }
        return <StackV gap={6} isSkeleton={isSkeleton} items={[comboMeterSection, cartListSection]} />
    }

    const previewSkeletonTotalRow = [
        () => <Skeleton className="h-5 w-20 rounded-lg" />,
        () => <Skeleton className="h-7 w-32 rounded-lg" />,
    ]
    const totalPriceRow = [
        () => <Typography size="base" weight="semibold" text={labels.total} />,
        ...(preview
            ? [() => (
                <PriceTagInline
                    discounted={preview.totalChargedVnd}
                    original={preview.totalListVnd}
                    currency="VND"
                />
            )]
            // preview failed to load ΓÇö fall back to the plain list
            // total (no bundle discount known) so the total is never blank.
            : previewError
                ? [() => <PriceTagInline discounted={fallbackTotalVnd} currency="VND" />]
                : []),
    ]
    const totalSummaryItems = [
        () => (
            <StackH
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                align="center"
                items={totalPriceRow}
            />
        ),
        ...(preview && preview.savingsVnd > 0
            ? [() => <Typography size="sm" color="success-soft" text={labels.savings} />]
            : []),
        ...(cheapestMonthlyLabel != null
            ? [() => <Typography size="xs" color="muted" text={labels.installmentHint} />]
            : []),
    ]
    const footerItems = [
        () => (
            isPreviewSkeleton ? (
                <StackH
                    gap={4}
                    principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    align="center"
                    items={previewSkeletonTotalRow}
                />
            ) : (
                <StackV gap={2} items={totalSummaryItems} />
            )
        ),
        () => (
            <Button
                variant="primary"
                size="lg"
                suffixIcon={ArrowRightIcon}
                isDisabled={isMutating}
                onPress={onCheckout}
                label={labels.checkout}
                classNames={["w-full"]}
            />
        ),
        () => (
            <Button
                variant="tertiary"
                onPress={onViewFullCart}
                label={labels.viewFullCart}
                classNames={["w-full"]}
            />
        ),
    ]
    const footerSection: ComponentTypeWithSkeleton = () => (
        <StackV gap={4} items={footerItems} />
    )

    return (
        <DrawerShell
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            placement={isMobile ? "bottom" : "right"}
            title={labels.header}
            dialogClassName="sm:max-w-md"
            isSkeleton={isSkeleton}
            body={cartBody}
            footer={items.length > 0 ? footerSection : undefined}
            // HeroUI's `.drawer__footer` hard-codes `flex-row items-center justify-end
            // gap-2` (drawer.css) ΓÇö this footer needs a vertical stack (summary above
            // full-width buttons), so every conflicting axis is forced with the trailing
            // `!` important modifier, same technique `DrawerShell` itself uses for `mt-0!`.
            footerClassName="flex-col! items-stretch! justify-start! gap-3! border-t"
            identity={{ tier: "overlay", component: "MiniCartDrawer" }}
        />
    )
}

import { type SelectOption, SelectSingle } from "@/components/atoms/forms"
import React from "react"
import { ArrowRightIcon, GraduationCapIcon, LockIcon } from "@phosphor-icons/react"
import { ModalShell } from "@/components/composites/layout/ModalShell"
import { Toolbar } from "@/components/composites/navigation/Toolbar"
import { SurfaceCard, SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import { InlineIconLabel } from "@/components/composites/text/InlineIconLabel"
import { PriceTagProminent, PriceTagInline, type PriceCurrency } from "@/components/blocks/commerce/PriceTag"
import { IconTile } from "@/components/atoms/display/IconTile"
import { Typography, type TypographyIcon } from "@/components/atoms/text/Typography"
import { Button } from "@/components/atoms/buttons/Button"
import { Spinner } from "@/components/atoms/display/Spinner"

import { StackV, StackH } from "@/components/frames/Stack"
import { PaymentType } from "@/modules/types/enums/payment-type"

/**
 * `_PaymentModal` ΓÇö the SRC TWIN of the shared payment overlay: order summary
 * ("Summary" panel) then gateway pick ("Payment" panel), for every paid flow
 * (course enroll - multi-course checkout - membership - AI subscription).
 * Presentational: typed props, already resolved; no fetch/store/i18n (that's
 * the connected half, `./index.tsx`).
 *
 * Only the price region skeletons (`isSkeleton` flows into the order's
 * `PriceTagInline`/`PriceTagProminent` leaves only) ΓÇö the tabs, installment
 * picker, voucher field and gateway list render immediately, mirroring
 * `PremiumGateModal`'s own "only the price region rests" contract.
 */

/** Which of the modal's two panels is showing ΓÇö freely switchable, not a wizard. */
export type PaymentModalTab = "summary" | "payment"

/** One course row of the multi-course cart summary. */
export interface PaymentModalCheckoutLine {
    /** Stable row key (the course id). */
    key: string
    /** Course title. */
    title: string
    /** Course cover image, when known. */
    coverUrl?: string | null
    /** Real charged price in the active currency; `undefined` while its preview hasn't resolved. */
    discounted?: number | null
    /** List price in the active currency, struck through when it beats {@link PaymentModalCheckoutLine.discounted}. */
    original?: number | null
}

/** One loyalty-breakdown row ΓÇö WHY the discount applies (course flow only). */
export interface PaymentModalLoyaltyRow {
    /** Stable row key. */
    key: string
    /** Leading icon, a COMPONENT reference ΓÇö never already-built JSX. */
    icon: TypographyIcon
    /** Already-translated reason line. */
    label: string
}

/** One gateway inside {@link PaymentModalGatewayGroup}. */
export interface PaymentModalGatewayMethod {
    /** The gateway. */
    type: PaymentType
    /** Gateway display name (e.g. "PayOS"). */
    name: string
    /** Already-translated one-line description. */
    description: string
    /** Gateway logo. */
    iconUrl: string
    /** Amount charged through this gateway, already formatted; omitted while the price hasn't resolved. */
    amountLabel?: string
    /** `true` while a checkout through THIS gateway is in flight ΓÇö swaps the row's trailing arrow for a spinner. */
    isPending: boolean
}

/** The gateway group for the active currency (domestic VND <-> international USD). */
export interface PaymentModalGatewayGroup {
    /** Group label (e.g. "Domestic"). */
    label: string
    /** Currency tag shown beside the label (e.g. "VND"). */
    currencyLabel: string
    /** Gateways in this group, in display order. */
    methods: ReadonlyArray<PaymentModalGatewayMethod>
}

/** All display text, already localized by the connected `PaymentModal`; a story passes i18n keys. */
export interface PaymentModalLabels {
    title: string
    tabsAria: string
    tabSummary: string
    tabPayment: string
    continueToPayment: string
    total: string
    priceError: string
    membershipPrice: string
    installmentTitle: string
    payFull: string
    payInstallment: string
    /** "3 months" ΓÇö set only once a term is chosen. */
    installmentMonths?: string
    /** "ΓÇª/month" ΓÇö set only once a term is chosen. */
    installmentPerMonth?: string
    /** Total + markup summary line ΓÇö set only once a term is chosen. */
    installmentSummary?: string
    voucherTitle: string
    voucherNone: string
    voucherVndOnlyHint: string
    currencyVnd: string
    currencyUsd: string
    secure: string
    noCardStored: string
}

/** Props for {@link _PaymentModal} ΓÇö presentational; all data resolved, no fetch/store/i18n. */
export interface PaymentModalProps {
    /** Whether the modal is currently open. */
    isOpen: boolean
    /** Open/close callback. */
    onOpenChange: (open: boolean) => void

    /** Which panel is showing. */
    selectedTab: PaymentModalTab
    /** Fired when the learner switches panels (via the tab strip, or the "Continue" CTA). */
    onSelectedTabChange: (tab: PaymentModalTab) => void

    /** Product name (course title / cart count / AI tier / membership). */
    orderName: string
    /** Course cover for the single-item summary icon tile; omitted for every other flow. */
    orderCoverUrl?: string | null
    /** Multi-course cart lines; omitted for every single-product flow. */
    checkoutLines?: ReadonlyArray<PaymentModalCheckoutLine>

    /** The charged price (single-item summary, or the cart's charged total) in the active currency. */
    discounted?: number | null
    /** The list price, struck through when it beats {@link PaymentModalProps.discounted}. */
    original?: number | null
    /** Active-phase price before loyalty ΓÇö feeds the breakdown popover's middle step (course flow only). */
    phase?: number | null
    /** Loyalty discount percent (0 = no loyalty row). */
    discountPercent: number
    /** `true` -> no numeric price exists yet; shows the flat membership heading instead of a `PriceTag`. */
    isMembershipFlow: boolean
    /** Loyalty breakdown rows (course flow only); empty elsewhere. */
    loyaltyRows: ReadonlyArray<PaymentModalLoyaltyRow>

    /** Currency the summary price + gateway list are shown in. */
    currency: PriceCurrency
    /**
     * `true` -> the price region rests: only the `PriceTagInline`/`PriceTagProminent`
     * leaves shimmer, the rest of the panel (tabs, installment, voucher, gateways)
     * renders immediately.
     */
    isSkeleton?: boolean
    /** `true` -> the price region failed to load; replaces it with an error message. */
    priceError?: boolean

    /** `true` -> the "pay in full / pay in installments" picker shows (course flows with terms offered). */
    installmentAvailable: boolean
    /** `true` -> an installment term is the active plan (clamps the order to VND). */
    installmentActive: boolean
    /** Fired when the learner toggles between "pay in full" and "pay in installments". */
    onInstallmentActiveChange: (active: boolean) => void

    /** `true` -> the apply-voucher field shows (course flow, with applicable vouchers). */
    showVoucher: boolean
    /** Options for the apply-voucher field ΓÇö a leading "no voucher" row plus one per applicable voucher. */
    voucherOptions: Array<SelectOption>
    /** Applied voucher code, `null` = none. */
    voucherCode: string | null
    /** Fired when the learner picks a voucher (or clears it). */
    onVoucherCodeChange: (code: string | null) => void
    /** `true` -> the applied voucher is VND-only (clamps the order to the domestic side). */
    flatVoucherActive: boolean

    /** `true` -> international (USD) gateways are usable for this order ΓÇö the currency toggle shows. */
    hasUsd: boolean
    /** Fired when the learner switches the domestic/international currency. */
    onCurrencyChange: (currency: PriceCurrency) => void

    /** Gateways for the active currency; omitted only while no flow context is open. */
    activeGroup?: PaymentModalGatewayGroup
    /** Fired when the learner picks a gateway row. */
    onSelectMethod: (type: PaymentType) => void
    /** `true` while any checkout mutation is in flight ΓÇö disables every gateway row. */
    isMutating: boolean

    labels: PaymentModalLabels
}

/**
 * One course row of the multi-course cart summary ΓÇö icon tile, truncated title, and
 * (once resolved) its real charged price.
 */
const checkoutLineRow = (
    line: PaymentModalCheckoutLine,
    currency: PriceCurrency,
    isSkeleton: boolean,
) => (
    <StackH
        gap={4}
        principle="content-row"
        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
        align="center"
        items={[
            () => (
                <IconTile
                    size="sm"
                    tone="accent"
                    icon={GraduationCapIcon}
                    src={line.coverUrl}
                    alt={line.title}
                />
            ),
            () => (
                <Typography
                    size="sm"
                    truncate
                    classNames={["min-w-0", "flex-1"]}
                    text={line.title}
                />
            ),
            ...(isSkeleton || line.discounted != null
                ? [() => (
                    <PriceTagInline
                        discounted={line.discounted ?? 0}
                        original={line.original}
                        currency={currency}
                        isSkeleton={isSkeleton}
                        showSavingLine={false}
                        classNames={["shrink-0"]}
                    />
                )]
                : []),
        ]}
    />
)

/** The order summary panel ΓÇö a multi-course cart list + total, or a single-item price + loyalty breakdown. */
const summaryContent = (props: PaymentModalProps) => {
    const {
        orderName,
        orderCoverUrl,
        checkoutLines,
        discounted,
        original,
        phase,
        discountPercent,
        isMembershipFlow,
        loyaltyRows,
        currency,
        isSkeleton = false,
        priceError = false,
        labels,
        onSelectedTabChange,
    } = props

    if (priceError) {
        return <AsyncContentError title={labels.priceError} />
    }

    if (checkoutLines != null) {
        const checkoutLineItems = checkoutLines.map((line) => () => checkoutLineRow(line, currency, isSkeleton))
        const totalRow = [
            () => <Typography size="sm" weight="semibold" text={labels.total} />,
            ...(isSkeleton || discounted != null
                ? [() => (
                    <PriceTagProminent
                        discounted={discounted ?? 0}
                        original={original}
                        currency={currency}
                        isSkeleton={isSkeleton}
                        showSavingLine={false}
                        classNames={["shrink-0"]}
                    />
                )]
                : []),
        ]
        const checkoutSummaryItems = [
            () => <StackV gap={4} items={checkoutLineItems} />,
            () => (
                <StackH
                    gap={4}
                    principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    justify="between"
                    items={totalRow}
                />
            ),
        ]
        return (
            <StackV
                gap={5}
                principle="group-boundary"
                explain="Section group spacing ΓÇö not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                divider
                items={checkoutSummaryItems}
            />
        )
    }

    const priceRegion = isSkeleton || discounted != null
        ? (
            <PriceTagProminent
                discounted={discounted ?? 0}
                original={original}
                currency={currency}
                isSkeleton={isSkeleton}
                breakdown={phase != null ? { phase, loyaltyPercent: discountPercent } : undefined}
            />
        )
        : isMembershipFlow
            ? <Typography size="h4" weight="bold" text={labels.membershipPrice} />
            : null

    const orderIdentityItems = [
        () => (
            <IconTile
                size="sm"
                tone="accent"
                icon={GraduationCapIcon}
                src={orderCoverUrl}
                alt={orderName}
            />
        ),
        () => (
            <StackV
                gap={3}
                classNames={["min-w-0", "flex-1"]}
                items={[
                    () => <Typography size="xs" color="muted" truncate text={orderName} />,
                    () => priceRegion,
                ]}
            />
        ),
    ]

    const singleSummaryItems = [
        () => (
            <StackH
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                align="center"
                items={orderIdentityItems}
            />
        ),
        ...(loyaltyRows.length > 0
            ? [() => (
                <StackV
                    gap={3}
                    items={loyaltyRows.map((row) => () => (
                        <InlineIconLabel icon={row.icon} label={row.label} tone="success" size="xs" />
                    ))}
                />
            )]
            : []),
        () => (
            <Button
                variant="primary"
                size="lg"
                suffixIcon={ArrowRightIcon}
                iconSlide
                classNames={["w-full"]}
                label={labels.continueToPayment}
                onPress={() => onSelectedTabChange("payment")}
            />
        ),
    ]

    return <StackV gap={4} items={singleSummaryItems} />
}

/** Trailing control for a gateway row - spinner while pending, else a chevron. */
interface GatewayTrailingProps {
    isPending: boolean
}

const GatewayTrailing = ({ isPending }: GatewayTrailingProps) => {
    if (isPending) {
        return <Spinner size="sm" />
    }
    return <ArrowRightIcon aria-hidden focusable="false" className="size-5 text-muted" />
}

/** One gateway row ΓÇö leading logo, name + description, amount, and a trailing arrow/spinner. */
const gatewayRow = (
    method: PaymentModalGatewayMethod,
    onSelectMethod: (type: PaymentType) => void,
    isMutating: boolean,
): SurfaceCardListItem => ({
    key: method.type,
    leading: () => (
        <img
            alt={method.name}
            className="h-8 w-12 shrink-0 object-contain object-left"
            src={method.iconUrl}
        />
    ),
    title: method.name,
    subtitle: method.description,
    metaText: method.amountLabel,
    trailing: () => <GatewayTrailing isPending={method.isPending} />,
    onPress: () => onSelectMethod(method.type),
    isDisabled: isMutating,
})

/** The payment panel ΓÇö installment picker, apply-voucher, currency toggle, gateway list, trust line. */
const paymentContent = (props: PaymentModalProps) => {
    const {
        installmentAvailable,
        installmentActive,
        onInstallmentActiveChange,
        showVoucher,
        voucherOptions,
        voucherCode,
        onVoucherCodeChange,
        flatVoucherActive,
        hasUsd,
        currency,
        onCurrencyChange,
        activeGroup,
        onSelectMethod,
        isMutating,
        labels,
    } = props

    const installmentMonthsRow = [
        () => <Typography size="sm" weight="semibold" text={labels.installmentMonths ?? ""} />,
        () => <Typography size="sm" color="muted" text={labels.installmentPerMonth ?? ""} />,
    ]

    const installmentSectionItems = [
        () => <Typography size="xs" weight="medium" color="muted" text={labels.installmentTitle} />,
        () => (
            <Toolbar
                variant="primary"
                size="sm"
                leftTabs={{
                    selectedKey: installmentActive ? "installment" : "full",
                    ariaLabel: labels.installmentTitle,
                    onSelectionChange: (key) => onInstallmentActiveChange(String(key) === "installment"),
                    items: [
                        { key: "full", label: labels.payFull },
                        { key: "installment", label: labels.payInstallment },
                    ],
                }}
            />
        ),
        ...(installmentActive && labels.installmentMonths != null
            ? [() => (
                <SurfaceCard
                    variant="nested"
                    padding={4}
                    body={() => (
                        <StackH
                            gap={4}
                            principle="content-row"
                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            justify="between"
                            items={installmentMonthsRow}
                        />
                    )}
                />
            )]
            : []),
        ...(labels.installmentSummary != null
            ? [() => <Typography size="xs" color="muted" text={labels.installmentSummary ?? ""} />]
            : []),
    ]

    const voucherSectionItems = [
        () => (
            <SelectSingle
                label={labels.voucherTitle}
                ariaLabel={labels.voucherTitle}
                placeholder={labels.voucherNone}
                options={voucherOptions}
                value={voucherCode ?? ""}
                onValueChange={(value) => onVoucherCodeChange(value || null)}
                isDisabled={isMutating}
            />
        ),
        ...(flatVoucherActive
            ? [() => <Typography size="xs" color="muted" text={labels.voucherVndOnlyHint} />]
            : []),
    ]

    const trustLineItems = [
        () => <InlineIconLabel icon={LockIcon} label={labels.secure} size="xs" />,
        () => <Typography size="xs" color="muted" text={labels.noCardStored} />,
    ]

    const paymentPanelItems = [
        ...(installmentAvailable
            ? [() => <StackV gap={4} items={installmentSectionItems} />]
            : []),
        ...(showVoucher
            ? [() => <StackV gap={4} items={voucherSectionItems} />]
            : []),
        ...(hasUsd
            ? [() => (
                <Toolbar
                    variant="primary"
                    leftTabs={{
                        selectedKey: currency,
                        ariaLabel: labels.title,
                        onSelectionChange: (key) => onCurrencyChange(String(key) as PriceCurrency),
                        items: [
                            { key: "VND", label: labels.currencyVnd },
                            { key: "USD", label: labels.currencyUsd },
                        ],
                    }}
                />
            )]
            : []),
        ...(activeGroup
            ? [() => (
                <SurfaceCardList
                    label={activeGroup.label}
                    labelEnd={activeGroup.currencyLabel}
                    items={activeGroup.methods.map((method) => gatewayRow(method, onSelectMethod, isMutating))}
                />
            )]
            : []),
        () => (
            <StackV
                gap={3}
                principle="sibling-stack"
                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                align="center"
                items={trustLineItems}
            />
        ),
    ]

    return <StackV gap={4} items={paymentPanelItems} />
}

/**
 * Shared payment modal for every paid flow. See the file header for the panel
 * layout and the `isSkeleton` contract.
 *
 * @param props - {@link PaymentModalProps}
 */
const _PaymentModal = (props: PaymentModalProps) => {
    const { isOpen, onOpenChange, selectedTab, onSelectedTabChange, labels } = props

    const body = () => (
        <StackV
            gap={6}
            items={[
                () => (
                    <Toolbar
                        leftTabs={{
                            selectedKey: selectedTab,
                            ariaLabel: labels.tabsAria,
                            onSelectionChange: (key) => onSelectedTabChange(String(key) as PaymentModalTab),
                            items: [
                                { key: "summary", label: labels.tabSummary },
                                { key: "payment", label: labels.tabPayment },
                            ],
                        }}
                    />
                ),
                () => (selectedTab === "summary" ? summaryContent(props) : paymentContent(props)),
            ]}
        />
    )

    return (
        <ModalShell
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            title={labels.title}
            size="sm"
            body={body}
            identity={{ tier: "overlay", component: "PaymentModal" }}
        />
    )
}

export { _PaymentModal }
